with filtered as (select id, product_id, quantity, last_restock, date_sub(last_restock, 20) as last_restock_minus_20d from inventory where last_restock >= to_date('2023-06-21') and product_id in (2, 8)) select *, lag(quantity, 1) over w_recent as prev_quantity, lag(quantity, 2) over w_recent as prev_quantity_2, first_value(quantity, true) over (partition by product_id order by last_restock, id rows between unbounded preceding and current row) as first_known_quantity from filtered where product_id in (1, 4, 8) window w_recent as (partition by product_id order by last_restock, id)
